#!/usr/bin/env python3
# luxarch:release-action-close hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""A release action is recorded as its issue closes: label, line and file together.

An issue whose work needs a step or a heads-up when it ships (a secret to set, a script to run, a
correction to the last release's notes, a breaking change to call out) says so as it closes, in
three places that must agree: the label `release-action` and a `Release: <the step>` line in its
close summary (what LuxPM shows and searches), and `release-actions/<KEY>.md` at the repo's root,
committed with the work (what the release that ships the work consumes, `release-actions-collected`,
`--doc FLEET-RELEASE-PROCESS` §3a). One without the others is lost.

PreToolUse(luxpm_update_issue, luxpm_create_issue). Each entry the call writes (the single form,
each `updates[]` entry, a create) is judged by what the issue will hold after the call: its labels
are the ones the entry sends (`labels` replaces them), else the ones LuxPM holds now, and its close
summary is the one the entry sends, else the one LuxPM holds. The call is denied when:

- the close summary the issue will hold has a `Release:` line (`Release action:` too, bold,
  bulleted or quoted; `Release: none`, or a version alone, names no step) and the issue will not
  carry `release-action`: a summary it writes, or one LuxPM holds while the call's `labels`
  replace a set that had the label;
- the issue will carry a label that is `release-action` in another case (`Release-Action`):
  LuxPM keeps a label as sent and filters labels exactly, so no release would list it;
- an issue it closes (`state: done`), or one it labels `release-action`, will carry the label and
  its close summary has no `Release:` line;
- an issue of this repo's project (the `.luxpm-receipt` of the checkout the call runs in) closes,
  or is closed, carrying the label and a line, and the checkout's HEAD has no
  `release-actions/<KEY>.md`; only a relabel of an issue already closed, sending no new summary,
  may rely on a file its history once added (a release consumed it);
- a create filed done carries the label and a line: its file cannot have been committed yet;
- an issue of this repo's project closes, or has its labels or summary changed, without them
  while HEAD holds `release-actions/<KEY>.md`.

An entry that changes neither the label, the close summary nor the state to `done` is not judged,
and neither is a cancelled issue: it ships nothing.
What an issue holds now is read from LuxPM itself (`_ledger.luxpm_issues`); with LuxPM unreadable,
an entry that needs it is denied, naming what to send so it does not.

A process gate, like `no-self-park`: an event it cannot read passes (Claude Code always sends
one it can), a crash while judging denies (`guarded`), and LuxPM unreadable denies.
"""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import guarded
from _ledger import (
    Issue,
    LuxPMUnread,
    luxpm_issues,
    read_event,
    repo_project,
    row_labels,
)
from _release_actions import RELEASE_ACTION_LABEL, action_path, release_steps

_UPDATE = "mcp__luxpm__luxpm_update_issue"
_CREATE = "mcp__luxpm__luxpm_create_issue"
_GIT_TIMEOUT = 10
# a NAME, not an inline `except (A, B)`: its formatting differs per Python target (PEP 758)
_GIT_ERRORS = (OSError, subprocess.SubprocessError)


class Checkout:
    """The git checkout the call runs in, and which of its issues' files it holds."""

    def __init__(self, cwd: str) -> None:
        self.root = Path(
            self._git(Path(cwd or "."), "rev-parse", "--show-toplevel").strip() or ""
        )
        self.project = (
            repo_project(self.root) if str(self.root) not in ("", ".") else ""
        )

    @staticmethod
    def _git(where: Path, *args: str) -> str:
        try:
            out = subprocess.run(
                ["git", "-C", str(where), *args],
                capture_output=True,
                text=True,
                timeout=_GIT_TIMEOUT,
                check=False,
            )
        except _GIT_ERRORS:
            return ""
        return out.stdout if out.returncode == 0 else ""

    def owns(self, key: str) -> bool:
        return bool(self.project) and key.split("-")[0] == self.project

    def holds(self, key: str) -> bool:
        return bool(
            self._git(
                self.root, "ls-tree", "--name-only", "HEAD", action_path(key)
            ).strip()
        )

    def ever_added(self, key: str) -> bool:
        return bool(
            self._git(
                self.root,
                "log",
                "--format=%h",
                "--diff-filter=A",
                "-1",
                "HEAD",
                "--",
                action_path(key),
            ).strip()
        )


def _entries(inp: dict[str, object]) -> list[dict[str, object]]:
    out = [inp]
    updates = inp.get("updates")
    if isinstance(updates, list):
        out += [u for u in updates if isinstance(u, dict)]
    return out


def _key(entry: dict[str, object], project: object) -> str:
    seq = str(entry.get("sequence_id") or "").strip().upper()
    if "-" in seq or not seq:
        return seq
    proj = str(entry.get("project") or project or "").strip().upper()
    return f"{proj}-{seq}" if proj else seq


def _labels(raw: object) -> list[str] | None:
    """The labels as sent, trimmed, case kept: LuxPM stores them so and filters them exactly."""
    if isinstance(raw, str):
        return [x.strip() for x in raw.split(",") if x.strip()]
    if isinstance(raw, list):
        return [str(x).strip() for x in raw]
    return None


def _held(row: Issue | None) -> list[str]:
    exact = row.get("labels_exact") if row else None
    return [str(x) for x in exact] if isinstance(exact, list) else []


def _judged(entry: dict[str, object]) -> bool:
    state = str(entry.get("state") or "").strip().lower()
    return state == "done" or "close_summary" in entry or "labels" in entry


def _needs_row(entry: dict[str, object]) -> bool:
    """The entry is judged on something it does not send itself."""
    return "labels" not in entry or "close_summary" not in entry


def _fault(
    entry: dict[str, object], row: Issue | None, create: bool, key: str, here: Checkout
) -> str:
    sent = _labels(entry.get("labels"))
    labels = (
        sent if sent is not None else ([] if create else _held(row) or row_labels(row))
    )
    labelled = RELEASE_ACTION_LABEL in labels
    variant = next(
        (
            x
            for x in labels
            if x.lower() == RELEASE_ACTION_LABEL and x != RELEASE_ACTION_LABEL
        ),
        "",
    )
    if "close_summary" in entry:
        summary: object = entry.get("close_summary")
    else:
        summary = row.get("close_summary") if row else ""
    steps = release_steps(summary)
    state = str(entry.get("state") or "").strip().lower()
    if state == "cancelled" or (not state and row and row.get("state") == "cancelled"):
        return ""  # a cancelled issue ships nothing
    if variant:
        return (
            f"it will carry `{variant}`, which LuxPM's exact label filter does not list as "
            f"`{RELEASE_ACTION_LABEL}`: send `labels` with it spelled `{RELEASE_ACTION_LABEL}`"
        )
    if steps and not labelled:
        return (
            f"its close summary names a release step ({steps[0][:80]!r}) but the issue will not "
            f"carry the `{RELEASE_ACTION_LABEL}` label: drop the `Release:` line when the release "
            f"needs nothing, or send `labels` with `{RELEASE_ACTION_LABEL}` added to the labels it "
            "has"
        )
    closed = (
        state == "done"
        or "close_summary" in entry
        or bool(row and row.get("state") == "done")
    )
    if labelled and not steps and closed:
        return (
            f"it carries `{RELEASE_ACTION_LABEL}` but its close summary has no "
            "`Release: <the step>` line, so the release that ships it has nothing to do: "
            "write the step, or drop the label when the release needs nothing"
        )
    if create:
        if labelled and steps and state == "done":
            return (
                "a create filed done cannot carry a release action, whose file must be committed "
                "first: create it open, commit its `release-actions/<KEY>.md`, then close it"
            )
        return ""
    if not here.owns(key):
        return ""
    path = action_path(key)
    # a relabel of an issue already closed, its step unchanged, whose file a release consumed
    relabel = (
        "close_summary" not in entry
        and state != "done"
        and bool(row and row.get("state") == "done")
        and here.ever_added(key)
    )
    if labelled and steps and closed and not here.holds(key) and not relabel:
        return (
            f"it records a release action but this checkout's HEAD has no `{path}`, so no "
            "release will consume it: commit the step there with the work, and run the close "
            "from the checkout that holds that commit (the issue's worktree)"
        )
    if (not labelled or not steps) and closed and here.holds(key):
        return (
            f"HEAD holds `{path}` but the issue will carry no release action: give it the "
            f"`{RELEASE_ACTION_LABEL}` label and a `Release:` line, or `git rm` the file"
        )
    return ""


def _faults(inp: dict[str, object], create: bool, here: Checkout) -> list[str]:
    entries = [inp] if create else _entries(inp)
    keyed = [
        (
            "the new issue"
            if create
            else (_key(e, inp.get("project")) or "this issue"),
            e,
        )
        for e in entries
        if _judged(e)
    ]
    wanted = [k for k, e in keyed if not create and "-" in k and _needs_row(e)]
    rows: dict[str, Issue] = {}
    if wanted:
        try:
            rows = luxpm_issues(wanted)
        except LuxPMUnread as exc:
            return [
                f"{k}: LuxPM could not be read ({exc}), and the labels or close summary it holds "
                "decide this; retry once LuxPM answers, or send both `labels` and `close_summary`"
                for k in wanted
            ]
    out: list[str] = []
    for key, e in keyed:
        if not create and "-" in key and _needs_row(e) and key not in rows:
            out.append(
                f"{key}: LuxPM knows no such issue, so what it holds cannot be read"
            )
            continue
        fault = _fault(e, rows.get(key), create, key, here)
        if fault:
            out.append(f"{key}: {fault}")
    return out


def main() -> int:
    ev = read_event()
    name = str(ev.get("tool_name") or "")
    ti = ev.get("tool_input")
    if name not in (_UPDATE, _CREATE) or not isinstance(ti, dict):
        return 0
    faults = _faults(ti, name == _CREATE, Checkout(str(ev.get("cwd") or "")))
    if not faults:
        return 0
    print(
        "DENIED by release-action-close: a release action is recorded with its label, its "
        "line and its file together.\n"
        + "".join(f"  - {f}\n" for f in faults)
        + "The release that ships the work consumes `release-actions/<KEY>.md` into its change\n"
        "log's `Release actions` section (--doc FLEET-RELEASE-PROCESS §3a).",
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    sys.exit(guarded(main, "release-action-close"))
